// Route-story narration.
// Hebrew: pre-generated ElevenLabs clips shipped with the app (public/audio/he/<seg>/<step>.mp3,
//         generated by scripts/gen-narration.mjs; src/data/narration-he.json holds a text hash per step
//         so a clip is used only while its text is unchanged). Clips are cached by the service worker
//         after first play, or pre-downloaded per segment / for the whole trail (Cache API "narration").
// English: the device's own speech synthesis.
import manifest from '../data/narration-he.json'

const BASE = import.meta.env.BASE_URL
export const CACHE = 'narration'

// must match scripts/gen-narration.mjs
export const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) } return (h >>> 0).toString(36) }
export const stepText = (i, n, txt) => `שלב ${i + 1} מתוך ${n}. ${txt}`

/** Clip for official step i (0-based, north→south order) of a segment, or null when missing/outdated. */
export function clipFor(segId, i, steps) {
  const e = manifest.segments?.[segId]?.[i]
  if (!e || e.hash !== hash(stepText(i, steps.length, steps[i]))) return null
  return { url: `${BASE}audio/he/${segId}/${i + 1}.mp3`, bytes: e.bytes }
}
export const segmentClips = (segId, steps) => steps.map((_, i) => clipFor(segId, i, steps))
export const narrationVoice = () => manifest.voice_name || 'ElevenLabs'
export function trailNarrationSize(segments) {
  let bytes = 0, clips = 0
  for (const s of segments) for (const c of segmentClips(s.id, s.steps_he || [])) if (c) { bytes += c.bytes; clips++ }
  return { bytes, clips }
}

// ---- player ----------------------------------------------------------------------------------
let audio = null, onEndCb = null
function player() {
  if (audio) return audio
  audio = new Audio(); audio.preload = 'auto'
  audio.addEventListener('ended', () => { const cb = onEndCb; onEndCb = null; cb?.() })
  audio.addEventListener('error', () => { const cb = onEndCb; onEndCb = null; cb?.(new Error('audio')) })
  return audio
}
/** Plays a clip URL; resolves when it ends, rejects on error. */
export function playClip(url) {
  const a = player()
  stopClip()
  a.src = url
  return new Promise((res, rej) => { onEndCb = (e) => (e ? rej(e) : res()); a.play().catch(rej) })
}
export function stopClip() { if (!audio) return; onEndCb = null; try { audio.pause(); audio.currentTime = 0 } catch { /* ignore */ } }

// ---- offline cache ---------------------------------------------------------------------------
const open = () => ('caches' in window ? caches.open(CACHE) : Promise.resolve(null))
export async function countCached(urls) {
  const c = await open(); if (!c) return 0
  let n = 0; for (const u of urls) if (await c.match(u)) n++
  return n
}
/** Downloads clips into the cache; onProgress(done, total). */
export async function prefetch(urls, onProgress, signal) {
  const c = await open(); if (!c) throw new Error('no cache')
  let done = 0
  for (const u of urls) {
    if (signal?.aborted) break
    if (!(await c.match(u))) { const r = await fetch(u, { cache: 'no-store' }); if (!r.ok) throw new Error(`HTTP ${r.status}`); await c.put(u, r) }
    done++; onProgress?.(done, urls.length)
  }
  return done
}
export async function cacheInfo() {
  const c = await open(); if (!c) return { clips: 0, bytes: 0 }
  const keys = await c.keys(); let bytes = 0
  for (const k of keys) { const r = await c.match(k); const b = await r?.blob(); bytes += b?.size || 0 }
  return { clips: keys.length, bytes }
}
export async function clearCache() { if ('caches' in window) await caches.delete(CACHE) }

// ---- device voice (English, and Hebrew fallback) ------------------------------------------------
const PREFERRED = { en: ['Samantha', 'Ava', 'Allison', 'Zoe', 'Daniel', 'Karen', 'Moira', 'Google US English', 'Microsoft Aria'], he: ['Carmit', 'Google עברית'] }
export function pickVoice(lang) {
  const synth = window.speechSynthesis; if (!synth) return null
  const voices = synth.getVoices().filter((v) => v.lang?.toLowerCase().startsWith(lang))
  for (const name of PREFERRED[lang] || []) { const v = voices.find((x) => x.name.includes(name)); if (v) return v }
  return voices.find((v) => !/compact|eloquence/i.test(v.name) && v.localService) || voices[0] || null
}
